 "content": "def transform(grid):
    # Move each colored connected object to the top or bottom edge according
    # to its pattern: compact framed/square motifs go to the top; other motifs go bottom.
    h, w = len(grid), len(grid[0])
    seen = set()
    out = [[0]*w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if not color or (r,c) in seen:
                continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    q=(y+dy,x+dx)
                    if 0<=q[0]<h and 0<=q[1]<w and q not in seen and grid[q[0]][q[1]]==color:
                        seen.add(q); stack.append(q)
            minr=min(y for y,x in cells); maxr=max(y for y,x in cells)
            minc=min(x for y,x in cells); maxc=max(x for y,x in cells)
            shape={(y-minr,x-minc) for y,x in cells}
            hh=maxr-minr+1; ww=maxc-minc+1
            # Symmetric, nearly square bounded motifs are the top group.
            top = hh <= 4 and ww <= 4 and len(shape) in (7,8,9,10,12) and all((hh-1-y,x) in shape for y,x in shape) and all((y,ww-1-x) in shape for y,x in shape)
            nr=0 if top else h-hh
            for y,x in shape:
                out[nr+y][minc+x]=color
    return out
